from itertools import groupby
from string import digits


def encode(text):
    """Encode runs, reserving ASCII digits for counts."""
    parts = []
    for char, run in groupby(text):
        if char in digits:
            raise ValueError("ASCII digits are reserved for counts")
        count = sum(1 for _ in run)
        if count > 1:
            parts.append(str(count))
        parts.append(char)
    return "".join(parts)


def decode(text):
    """Expand characters with optional decimal run lengths."""
    parts = []
    index = 0
    while index < len(text):
        start = index
        while index < len(text) and text[index] in digits:
            index += 1
        count = 1
        if index > start:
            if index == len(text):
                raise ValueError("count requires a following character")
            if text[start] == "0" or text[start:index] == "1":
                raise ValueError("count must be at least two without leading zeros")
            count = int(text[start:index])
        parts.append(text[index] * count)
        index += 1
    return "".join(parts)
